"""An empty golden-question suite must not pass (Codex finding on PR #36)."""

from __future__ import annotations

from knowledge_engine_ai.retrieval_benchmark import GoldenQuestion, evaluate_retrieval
from knowledge_engine_ai.retrieval_benchmark_runner import (
    GoldenBenchmarkRun,
    GoldenBenchmarkSuite,
)


def _run(question_id: str, retrieved: tuple[str, ...]) -> GoldenBenchmarkRun:
    question = GoldenQuestion(
        question_id=question_id,
        domain="glp1",
        question="Does treatment help?",
        required_evidence_ids=("ev-a",),
        qualifier_evidence_ids=(),
    )
    return GoldenBenchmarkRun(question=question, result=evaluate_retrieval(question, retrieved))


def test_a_suite_that_ran_no_questions_does_not_pass() -> None:
    assert GoldenBenchmarkSuite(limit=10, runs=()).passes is False


def test_a_suite_whose_every_question_passes_still_passes() -> None:
    suite = GoldenBenchmarkSuite(limit=10, runs=(_run("q1", ("ev-a",)), _run("q2", ("ev-a",))))

    assert suite.passes is True


def test_one_failing_question_fails_the_suite() -> None:
    suite = GoldenBenchmarkSuite(limit=10, runs=(_run("q1", ("ev-a",)), _run("q2", ())))

    assert suite.passes is False

from knowledge_engine.extraction.sections import detect_sections
from knowledge_engine.parser import ParsedPage


def _types(text: str) -> list[str]:
    return [span.section_type for span in detect_sections([ParsedPage(page_number=1, text=text)])]


def test_roman_numbered_headings_are_recognized() -> None:
    text = "I. Introduction\nWhy.\nII. Methods\nHow.\nIII. RESULTS\nWhat.\nIV. Discussion\nSo.\n"
    assert _types(text) == ["introduction", "methods", "results", "discussion"]


def test_roman_numbered_inline_label_is_recognized() -> None:
    assert _types("V. Conclusions: the effect was small.\n") == ["conclusion"]


def test_digit_numbering_and_unnumbered_headings_still_match() -> None:
    assert _types("2. Methods\nHow.\n3.1 Results\nWhat.\nReferences\n") == [
        "methods",
        "results",
        "references",
    ]


def test_roman_numbering_does_not_make_combined_or_mid_sentence_headings_match() -> None:
    assert _types("II. Results and Discussion\nText.\nIn results we saw more.\n") == []

from knowledge_engine.extraction.sections import detect_sections
from knowledge_engine.parser import ParsedPage


def _types(text: str) -> list[str]:
    return [span.section_type for span in detect_sections([ParsedPage(page_number=1, text=text)])]


def test_methodology_heading_is_a_methods_section() -> None:
    assert _types("Methodology\nWe sampled.\nResults\nIt worked.\n") == ["methods", "results"]


def test_patients_and_subjects_methods_headings_are_methods_sections() -> None:
    assert _types("2. Patients and Methods\nCohort.\n") == ["methods"]
    assert _types("Subjects and methods: adults aged 40-65.\n") == ["methods"]


def test_existing_methods_headings_still_match_and_prose_does_not() -> None:
    assert _types("Materials and Methods\nHow.\nStudy design\nWhy.\n") == ["methods", "methods"]
    assert _types("Our methodology was simple.\n") == []

